using Azure.AI.OpenAI;
using Azure.Identity;
using OpenAI;

namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Resolves an IChatClient matching the app's registration.
    /// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:1
    /// Reads ConnectionStrings:chat from user-secrets or env vars.
    /// </summary>
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);
        var host = builder.Build();

        var connStr = host.Services.GetRequiredService<IConfiguration>()
            .GetConnectionString("chat");

        if (string.IsNullOrEmpty(connStr))
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but ConnectionStrings:chat is not configured. " +
                "Wire one of:\n" +
                "  dotnet user-secrets init --project MyApp.Evals.Tests\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" " +
                "--project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name.");
        }

        return CreateFromConnectionString(connStr, "gpt-4o-mini");
    }

    internal static IChatClient CreateFromConnectionString(string connStr, string deploymentName)
    {
        var parts = connStr.Split(';')
            .Select(p => p.Split('=', 2))
            .Where(p => p.Length == 2)
            .ToDictionary(p => p[0].Trim(), p => p[1].Trim(), StringComparer.OrdinalIgnoreCase);

        var endpoint = parts.GetValueOrDefault("Endpoint")
            ?? throw new InvalidOperationException("Connection string missing Endpoint.");
        var deployment = parts.GetValueOrDefault("DeploymentId") ?? deploymentName;

        AzureOpenAIClient client;
        if (parts.TryGetValue("Key", out var key) && !string.IsNullOrEmpty(key))
            client = new AzureOpenAIClient(new Uri(endpoint), new System.ClientModel.ApiKeyCredential(key));
        else
            client = new AzureOpenAIClient(new Uri(endpoint), new DefaultAzureCredential());

        return client.GetChatClient(deployment).AsIChatClient();
    }
}

